// Flatten all previously used topics into a lowercase array for comparison
const topics = items.map(i => (i.json.Topic || '').toString().trim().toLowerCase()).filter(Boolean);
// Rotate through development stages by post count, so the feed covers the whole lifecycle
const STAGES = [
  'Discovery і збір вимог', 'Оцінка та планування', 'UX-дослідження', 'UI-дизайн',
  'Архітектура', 'Вибір технологічного стеку', 'Бекенд-розробка', 'Фронтенд-розробка',
  'Інтеграції та API', 'Тестування і QA', 'DevOps і CI/CD', 'Безпека',
  'Продуктивність', 'Реліз', 'Підтримка й розвиток', 'Комунікація з клієнтом',
];
const stage = STAGES[topics.length % STAGES.length];
return [{ json: { usedTopics: topics, retryCount: 0, stage } }];

const raw = $json.choices?.[0]?.message?.content || '';
const topic = raw.replace(/[\n\r"'«»]/g, '').replace(/[.]+$/, '').trim();
const used = $('Code - Build Used-Topics List').first().json.usedTopics;
let retryCount = 0;
try { retryCount = $('Code - Increment Retry Counter').last().json.retryCount || 0; } catch (e) {}
const isDuplicate = used.includes(topic.toLowerCase());
return [{ json: { topic, isDuplicate, retryCount } }];

// Safety net: after max retries, force uniqueness with a timestamp suffix
let topic = $json.topic;
if ($json.isDuplicate) {
  topic = `${topic} (${new Date().toISOString().slice(0,10)})`;
}
return [{ json: { topic } }];

