const raw = $json.choices?.[0]?.message?.content || '';
const topic = $('Code - Finalize Unique Topic').first().json.topic;
let obj = {};
try { obj = JSON.parse(raw.replace(/^```(?:json)?\s*|\s*```$/g, '')); } catch (e) {}

let prompt = (obj.image_prompt || '').toString().trim()
  || 'modern software development team at work, laptops with code, dark office, blue accent lighting, cinematic';
// Safety net: hard-cap length so the Pollinations URL stays within safe limits.
const MAX_CHARS = 400;
if (prompt.length > MAX_CHARS) {
  const cut = prompt.slice(0, MAX_CHARS);
  const lastComma = cut.lastIndexOf(',');
  prompt = (lastComma > 100 ? cut.slice(0, lastComma) : cut).trim();
}
// Collapse any accidental duplicate comma-separated tags
const seen = new Set();
prompt = prompt.split(',').map(t => t.trim()).filter(t => {
  const key = t.toLowerCase();
  if (!t || seen.has(key)) return false;
  seen.add(key);
  return true;
}).join(', ');

// Text rendered on the image: keep it short so it fits the layout
const stage_label = (obj.stage_label || 'Веб-розробка').toString().trim().slice(0, 30);
let headline = (obj.headline || topic).toString().trim().replace(/[.!]+$/, '');
if (headline.length > 70) headline = headline.slice(0, 70).replace(/\s+\S*$/, '');

return [{ json: { image_prompt: prompt, topic, stage_label, headline } }];

let raw = ($json.choices?.[0]?.message?.content || '').trim();

// Quality gate: no invented stats, no Russian-only letters. Ask Groq to fix up to 2 times.
const problems = t => {
  const p = [];
  if (/\d\s*%|\d+\s*(?:раз|разів|рази)\b|\d+\s*[-–‑]\s*\d+\s*%/i.test(t)) p.push('прибери всі відсотки, цифри економії та статистику');
  if (/[ыэъё]/i.test(t)) p.push('заміни всі російські слова й літери (ы, э, ъ, ё) на правильні українські');
  return p;
};
for (let i = 0; i < 2 && problems(raw).length; i++) {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.groq.com/openai/v1/chat/completions',
    headers: { Authorization: `Bearer ${$env.GROQ_API_KEY}`, 'Content-Type': 'application/json' },
    body: {
      model: 'openai/gpt-oss-120b', reasoning_effort: 'low', temperature: 0.3, max_tokens: 3000,
      messages: [
        { role: 'system', content: 'Ти редактор українських текстів. Повертаєш ЛИШЕ виправлений текст поста без коментарів, зберігаючи структуру, емодзі й хештеги.' },
        { role: 'user', content: `Виправ текст: ${problems(raw).join('; ')}.\n\n${raw}` },
      ],
    },
    json: true,
  });
  raw = (res.choices?.[0]?.message?.content || raw).trim();
}
// Last-resort cleanup of any remaining percentage fragments like "на 30-40 %"
raw = raw.replace(/\s*(?:на|до|у|в)?\s*~?\d+(?:[.,]\d+)?(?:\s*[-–‑]\s*\d+(?:[.,]\d+)?)?\s*%/g, '');
raw = raw.replace(/\*\*/g, '');

// Pull hashtag-only lines out of the body, then rebuild them: max 10, #bramblingtech always first
const tagRe = /#[\p{L}\p{N}_]+/gu;
const bodyLines = [];
const tags = [];
for (const line of raw.split('\n')) {
  const t = line.trim();
  if (t && t.split(/\s+/).every(w => w.startsWith('#'))) tags.push(...(t.match(tagRe) || []));
  else bodyLines.push(line);
}
const uniq = [];
for (const tag of ['#bramblingtech', ...tags]) {
  if (!uniq.some(u => u.toLowerCase() === tag.toLowerCase())) uniq.push(tag);
}
const body = bodyLines.join('\n').trim().slice(0, 2000);
return [{ json: { caption: `${body}\n\n${uniq.slice(0, 10).join(' ')}`, hashtags: uniq.slice(0, 10) } }];

// Consolidate whatever data/error made it here into one clean failure record
const src = items[0]?.json || {};
const errorMessage = src.error?.message || src.message || JSON.stringify(src).slice(0, 500) || 'Unknown error - see execution log';
return [{ json: {
  date: new Date().toISOString().slice(0,10),
  topic: $('Pollinations - Build Image URL (FREE)').first()?.json?.topic || 'N/A',
  caption: '',
  image_prompt: '',
  image_url: '',
  instagram_url: '',
  status: 'FAILED',
  error_message: errorMessage
} }];

