// Light brand layout built with Cloudinary transformations:
// white canvas, rounded photo card, blue stage pill, black headline, optional blue hashtags, blue logo.
// Colors from bramblingtech.com: #2b59f8 blue, #070707 black, white. Roboto has proper Cyrillic in Cloudinary.
const up = $('Cloudinary - Host Image').first().json;
const { stage_label, headline } = $('Pollinations - Build Image URL (FREE)').first().json;
// Cloudinary text layers: URL-encode, then double-escape , and /
const enc = s => encodeURIComponent(s).replace(/%2C/g, '%252C').replace(/%2F/g, '%252F');

// Sometimes (about half the posts) show 2 short topical hashtags + #bramblingtech on the image
const topical = ($json.hashtags || []).filter(h => h.toLowerCase() !== '#bramblingtech' && h.length <= 18);
const showTags = Math.random() < 0.5 && topical.length >= 2;
const tagLine = showTags ? ['#bramblingtech', ...topical.slice(0, 2)].join('  ') : '';

const t = [
  'c_crop,g_north,w_1.0,h_0.93',                 // cut off the Pollinations watermark strip
  'c_fill,g_auto,w_1000,h_560',
  'r_28',
  'c_mpad,w_1000,h_600,g_south,b_white',         // 40px top margin
  'c_mpad,w_1080,h_1080,g_north,b_white',        // white canvas below the photo
  `l_text:Roboto_24_bold_letter_spacing_3:${enc(' ' + stage_label.toUpperCase() + ' ')},co_white,b_rgb:2b59f8,bo_12px_solid_rgb:2b59f8/fl_layer_apply,g_north_west,x_52,y_640`,
  `l_text:Roboto_60_bold_line_spacing_-4:${enc(headline)},co_rgb:070707,c_fit,w_990,h_240/fl_layer_apply,g_north_west,x_40,y_705`,
  ...(tagLine ? [`l_text:Roboto_26_bold:${enc(tagLine)},co_rgb:2b59f8/fl_layer_apply,g_south_west,x_40,y_62`] : []),
  // Original blue logo from bramblingtech.com (brand/bramblingtech-logo.svg), uploaded to Cloudinary with this public_id
  'l_bramblingtech-logo,w_210/fl_layer_apply,g_south_east,x_40,y_48',
  'f_jpg,q_90',
];
const branded_image_url = `https://res.cloudinary.com/${$env.CLOUDINARY_CLOUD_NAME}/image/upload/${t.join('/')}/${up.public_id}.jpg`;
return [{ json: { ...$json, branded_image_url } }];
